// Normalize Inputs — v1.0 (Run Once / ALL)
// Augments item with identity/inputs and preserves original fields.
const item = $input.first() || { json: {} };
const base = item.json || {};

function good(x){
  if (x === undefined || x === null) return false;
  if (typeof x === 'string') return x.trim() !== '' && x.trim().toLowerCase() !== 'unknown';
  return true;
}
function pickNE(){ for (const a of arguments){ if (good(a)) return a; } return null; }
function trimStr(s){ return typeof s === 'string' ? s.trim() : s; }

const orderId        = trimStr(pickNE(base.orderId, base.amazonOrderId, base.orderData?.amazonOrderId));
const characterHash  = trimStr(pickNE(base.characterHash, base.orderData?.characterHash));
const childNameRaw   = pickNE(base.inputs?.childName, base.characterSpecs?.childName, base.orderData?.characterSpecs?.childName);
const dedicationRaw  = pickNE(base.inputs?.dedicationMessage, base.bookSpecs?.dedicationMessage, base.orderDetails?.dedicationMessage, '');

const childName = typeof childNameRaw === 'string' ? childNameRaw.trim() : childNameRaw;
const dedicationMessage = typeof dedicationRaw === 'string' ? dedicationRaw.trim() : '';

if (!good(childName)) {
  throw new Error('3A Phase 1: Missing required childName. Provide a non-empty child name before rendering.');
}
if (!good(characterHash)) {
  throw new Error('3A Phase 1: Missing required characterHash. Ensure SW1/SW2 emitted the character hash.');
}

const identity = { orderId, characterHash };
const inputs   = { childName, dedicationMessage };

return [{ json: { ...base, identity, inputs } }];

// Resolve Asset Paths — v1.0 (Run Once / ALL)
// Adds renderContext with canonical R2 keys; preserves original fields.
const item = $input.first() || { json: {} };
const base = item.json || {};

function req(name, val){
  if (val === undefined || val === null || (typeof val === 'string' && val.trim() === '')) {
    throw new Error(`3A Phase 1: Missing required field: ${name}`);
  }
  return typeof val === 'string' ? val.trim() : val;
}

const orderId       = req('identity.orderId', base.identity?.orderId || base.orderId || base.amazonOrderId);
const characterHash = req('identity.characterHash', base.identity?.characterHash || base.characterHash);
const childName     = req('inputs.childName', base.inputs?.childName || base.characterSpecs?.childName);
const dedicationMsg = typeof (base.inputs?.dedicationMessage ?? '') === 'string' ? base.inputs.dedicationMessage : '';

const renderContext = {
  font:        'book-mvp-simple-adventure/fonts/custom-font.ttf',
  coversBg:    'book-mvp-simple-adventure/backgrounds/page00-covers.png',
  dedicationBg:'book-mvp-simple-adventure/backgrounds/page00-dedication.png',
  p05Overlay:  'book-mvp-simple-adventure/overlays/animal-tracks/page05-meadow-footprints.png',
  p12Overlay:  null, // optional; set when finalized
  pose00:      `book-mvp-simple-adventure/characters/${characterHash}/pose00.png`,
  sizes: {
    interior: { w: 2625, h: 2625 },
    cover:    { w: 5203, h: 2625 }
  }
};

['font','coversBg','dedicationBg','p05Overlay','pose00'].forEach(k => {
  if (!renderContext[k] || typeof renderContext[k] !== 'string') {
    throw new Error(`3A Phase 1: Missing canonical key for ${k}`);
  }
});

return [{ json: { ...base, renderContext } }];
